<?php $edit = $edit ?? null;
$assigned = [];
if ($edit) foreach ($app->storage->read('user_roles.csv', ['user_id', 'role_id']) as $row) if ($row['user_id'] === $edit['id']) $assigned[] = $row['role_id']; ?><h1><?= $edit ? 'Editar usuário' : 'Novo usuário' ?></h1>
<form method="post" action="<?= $edit ? '/admin/users/' . e($edit['id']) : '/admin/users' ?>"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><?php if ($edit): ?><input type="hidden" name="_method" value="PATCH"><?php endif; ?><label>Nome <input name="name" value="<?= e($edit['name'] ?? '') ?>" required></label><label>Usuário <input name="username" value="<?= e($edit['username'] ?? '') ?>" <?= $edit ? 'readonly' : 'required' ?>></label><label>Senha <input type="password" name="password" <?= $edit ? '' : 'required' ?> minlength="8"></label><?php if ($edit): ?><label><input type="checkbox" name="active" value="1" <?= $edit['active'] === '1' ? 'checked' : '' ?>> Ativo</label><?php endif; ?><label>Perfis</label><?php foreach ($roles as $role): ?><label><input type="checkbox" name="roles[]" value="<?= e($role['id']) ?>" <?= in_array($role['id'], $assigned, true) ? 'checked' : '' ?>> <?= e($role['name']) ?></label><?php endforeach; ?><button type="submit">Salvar</button></form>